# G-Assist Plugin SDK for Node.js

A simple SDK for building G-Assist plugins in Node.js.

## Requirements

- Node.js 14.0 or later

## Installation

Copy `gassist-sdk.js` to your plugin folder, or:

```bash
npm install ./path/to/sdk/nodejs
```

## Quick Start

```javascript
const { Plugin } = require('./gassist-sdk');

const plugin = new Plugin('my-plugin', '1.0.0', 'My awesome plugin');

// Register a command
plugin.command('greet', (args) => {
    const name = args.name || 'World';
    return `Hello, ${name}!`;
});

// Run the plugin
plugin.run();
```

## Features

### Command Registration

```javascript
plugin.command('function_name', (args) => {
    // Access arguments
    const param = args.param || 'default';

    // Return result (string, object, etc.)
    return { result: 'value' };
});
```

### Async Commands

```javascript
plugin.command('fetch_data', async (args) => {
    const response = await fetch(args.url);
    const data = await response.json();
    return data;
});
```

### Streaming Output

```javascript
plugin.command('long_operation', (args) => {
    plugin.stream('Starting...\n');
    // do work
    plugin.stream('50% complete...\n');
    // do more work
    plugin.stream('Done!\n');
    return '';  // All output was streamed
});
```

### Passthrough Mode

```javascript
plugin.command('start_chat', (args) => {
    plugin.setKeepSession(true);
    return 'Chat started! Type "exit" to leave.';
});

plugin.command('on_input', (args) => {
    const content = args.content;

    if (content.toLowerCase() === 'exit') {
        plugin.setKeepSession(false);
        return 'Goodbye!';
    }

    plugin.setKeepSession(true);
    return `You said: ${content}`;
});
```

## Running Your Plugin

```bash
node plugin.js
```

## Manifest File

Create `manifest.json` alongside your plugin:

```json
{
    "manifestVersion": 1,
    "name": "my-plugin",
    "version": "1.0.0",
    "description": "My Node.js plugin",
    "executable": "node plugin.js",
    "persistent": true,
    "protocol_version": "2.0",
    "functions": [
        {
            "name": "greet",
            "description": "Greet the user",
            "tags": ["hello", "greet"],
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name to greet"
                }
            }
        }
    ]
}
```

## Logs

Plugin logs are written to:
```
%PROGRAMDATA%\NVIDIA Corporation\nvtopps\rise\plugins\<plugin-name>\<plugin-name>.log
```

## API Reference

### Plugin Class

```javascript
const plugin = new Plugin(name, version, description);
```

#### Methods

- `plugin.command(name, handler)` - Register a command handler
- `plugin.stream(data)` - Send streaming data
- `plugin.setKeepSession(keep)` - Set passthrough mode
- `plugin.log(message)` - Write to log file
- `plugin.run()` - Start the plugin main loop

## Protocol

This SDK implements Protocol V2 (JSON-RPC 2.0) with length-prefixed framing.
See `PROTOCOL_V2.md` in the Python SDK for full protocol documentation.

# G-Assist Plugin SDK for C++

A single-header SDK for building G-Assist plugins in C++.

## Requirements

- C++17 or later
- [nlohmann/json](https://github.com/nlohmann/json) library

## Installation

1. Copy `gassist_sdk.hpp` to your project
2. Download `nlohmann/json.hpp` from https://github.com/nlohmann/json/releases

## Quick Start

```cpp
#include <nlohmann/json.hpp>
#include "gassist_sdk.hpp"

using json = nlohmann::json;

int main() {
    gassist::Plugin plugin("hello-world", "1.0.0", "A simple example plugin");

    // Register a command
    plugin.command("say_hello", [&](const json& args) -> json {
        std::string name = args.value("name", "World");
        return "Hello, " + name + "!";
    });

    // Register command with streaming
    plugin.command("count", [&](const json& args) -> json {
        int count_to = args.value("count_to", 5);

        for (int i = 1; i <= count_to; i++) {
            plugin.stream("Counting: " + std::to_string(i) + "\n");
        }

        return "Done counting!";
    });

    // Run the plugin
    plugin.run();
    return 0;
}
```

## Features

### Command Registration

```cpp
plugin.command("function_name", [&](const json& args) -> json {
    // Access arguments
    std::string param = args.value("param", "default");

    // Return result (string, number, object, etc.)
    return {{"result", "value"}};
});
```

### Streaming Output

```cpp
plugin.command("long_operation", [&](const json& args) -> json {
    plugin.stream("Starting...\n");
    // do work
    plugin.stream("50% complete...\n");
    // do more work
    plugin.stream("Done!\n");
    return "";
});
```

### Passthrough Mode

```cpp
plugin.command("start_chat", [&](const json& args) -> json {
    plugin.set_keep_session(true);
    return "Chat started! Type 'exit' to leave.";
});

plugin.command("on_input", [&](const json& args) -> json {
    std::string content = args.value("content", "");

    if (content == "exit") {
        plugin.set_keep_session(false);
        return "Goodbye!";
    }

    plugin.set_keep_session(true);
    return "You said: " + content;
});
```

## Building

### Visual Studio

1. Create a new Console Application project
2. Add `gassist_sdk.hpp` and `nlohmann/json.hpp` to your project
3. Set C++ Language Standard to C++17 or later
4. Build as Release x64

### CMake

```cmake
cmake_minimum_required(VERSION 3.15)
project(my_plugin)

set(CMAKE_CXX_STANDARD 17)

add_executable(my_plugin plugin.cpp)
target_include_directories(my_plugin PRIVATE ${CMAKE_SOURCE_DIR}/include)
```

### Command Line (MSVC)

```batch
cl /EHsc /std:c++17 /O2 plugin.cpp /Fe:g-assist-plugin-myplugin.exe
```

## Manifest File

Create `manifest.json` alongside your executable:

```json
{
    "manifestVersion": 1,
    "name": "my-plugin",
    "version": "1.0.0",
    "description": "My C++ plugin",
    "executable": "g-assist-plugin-myplugin.exe",
    "persistent": true,
    "protocol_version": "2.0",
    "functions": [
        {
            "name": "say_hello",
            "description": "Greet the user",
            "tags": ["hello", "greet"],
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name to greet"
                }
            }
        }
    ]
}
```

## Logs

Plugin logs are written to:
```
%PROGRAMDATA%\NVIDIA Corporation\nvtopps\rise\plugins\<plugin-name>\<plugin-name>.log
```

## Protocol

This SDK implements Protocol V2 (JSON-RPC 2.0) with length-prefixed framing.
See `PROTOCOL_V2.md` in the Python SDK for full protocol documentation.

// SPDX-FileCopyrightText: Copyright (c) 2025 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
// SPDX-License-Identifier: Apache-2.0
//
// G-Assist Plugin SDK for Node.js (Protocol V2 - JSON-RPC 2.0)
//
// Usage:
//   const { Plugin } = require('./gassist-sdk');
//
//   const plugin = new Plugin('my-plugin', '1.0.0');
//
//   plugin.command('greet', (args) => {
//       return `Hello, ${args.name || 'World'}!`;
//   });
//
//   plugin.run();

const fs = require('fs');
const path = require('path');

// ============================================================================
// Protocol Handler
// ============================================================================

class Protocol {
    constructor() {
        this.MAX_MESSAGE_SIZE = 10 * 1024 * 1024; // 10MB
        this.closed = false;
        this.buffer = Buffer.alloc(0);
    }

    async readMessage() {
        if (this.closed) return null;

        try {
            // Read 4-byte length header
            const header = await this._readBytes(4);
            if (!header) {
                this.closed = true;
                return null;
            }

            const length = header.readUInt32BE(0);

            if (length > this.MAX_MESSAGE_SIZE || length === 0) {
                throw new Error(`Invalid message length: ${length}`);
            }

            // Read JSON payload
            const payload = await this._readBytes(length);
            if (!payload) {
                this.closed = true;
                return null;
            }

            // Parse JSON
            const message = JSON.parse(payload.toString('utf-8'));
            return message;

        } catch (err) {
            if (err.message !== 'EOF') {
                console.error('Protocol read error:', err.message);
            }
            this.closed = true;
            return null;
        }
    }

    writeMessage(message) {
        if (this.closed) return false;

        try {
            // Ensure jsonrpc field
            if (!message.jsonrpc) {
                message.jsonrpc = '2.0';
            }

            // Serialize to JSON
            const payload = Buffer.from(JSON.stringify(message), 'utf-8');

            if (payload.length > this.MAX_MESSAGE_SIZE) {
                return false;
            }

            // Create length-prefixed message
            const header = Buffer.alloc(4);
            header.writeUInt32BE(payload.length, 0);

            // Write to stdout
            process.stdout.write(header);
            process.stdout.write(payload);

            return true;
        } catch (err) {
            console.error('Protocol write error:', err.message);
            return false;
        }
    }

    close() {
        this.closed = false;
    }

    _readBytes(count) {
        return new Promise((resolve, reject) => {
            const tryRead = () => {
                // Check if we have enough data in buffer
                if (this.buffer.length >= count) {
                    const result = this.buffer.slice(0, count);
                    this.buffer = this.buffer.slice(count);
                    resolve(result);
                    return;
                }

                // Need more data
                const chunk = process.stdin.read();
                if (chunk) {
                    this.buffer = Buffer.concat([this.buffer, chunk]);
                    tryRead();
                } else {
                    // Wait for more data
                    process.stdin.once('readable', tryRead);
                    process.stdin.once('end', () => resolve(null));
                    process.stdin.once('error', reject);
                }
            };

            tryRead();
        });
    }
}

// ============================================================================
// Plugin Class
// ============================================================================

class Plugin {
    constructor(name, version, description = '') {
        this.name = name;
        this.version = version;
        this.description = description;

        this.protocol = new Protocol();
        this.commands = new Map();
        this.running = false;
        this.currentRequestId = null;
        this.keepSession = false;

        // Setup logging
        this.logFile = null;
        this._setupLogging();

        this.log(`Plugin '${name}' v${version} initialized`);
    }

    _setupLogging() {
        const pluginDir = this._getPluginDir();
        try {
            if (!fs.existsSync(pluginDir)) {
                fs.mkdirSync(pluginDir, { recursive: true });
            }
            const logPath = path.join(pluginDir, `${this.name}.log`);
            this.logFile = fs.createWriteStream(logPath, { flags: 'a' });
        } catch (err) {
            // Ignore logging errors
        }
    }

    _getPluginDir() {
        const programData = process.env.PROGRAMDATA || process.env.HOME || '.';
        if (process.platform === 'win32') {
            return path.join(programData, 'NVIDIA Corporation', 'nvtopps', 'rise', 'plugins', this.name);
        }
        return path.join(programData, '.gassist', 'plugins', this.name);
    }

    log(message) {
        const timestamp = new Date().toISOString();
        const line = `${timestamp} ${message}\n`;
        if (this.logFile) {
            this.logFile.write(line);
        }
    }

    /**
     * Register a command handler
     * @param {string} name - Command name
     * @param {function} handler - Handler function (args) => result
     */
    command(name, handler) {
        this.commands.set(name, handler);
        this.log(`Registered command: ${name}`);
    }

    /**
     * Send streaming data during command execution
     * @param {string} data - Data to stream
     */
    stream(data) {
        if (this.currentRequestId === null) return;

        this.protocol.writeMessage({
            jsonrpc: '2.0',
            method: 'stream',
            params: {
                request_id: this.currentRequestId,
                data: data
            }
        });
    }

    /**
     * Set passthrough mode
     * @param {boolean} keep - Whether to keep session open
     */
    setKeepSession(keep) {
        this.keepSession = keep;
    }

    /**
     * Run the plugin main loop
     */
    async run() {
        this.log('Starting plugin main loop');
        this.running = true;

        // Set stdin to raw mode for binary reading
        if (process.stdin.setRawMode) {
            process.stdin.setRawMode(true);
        }
        process.stdin.resume();

        while (this.running) {
            const message = await this.protocol.readMessage();
            if (!message) break;

            await this._handleMessage(message);
        }

        this.log('Plugin stopped');
        process.exit(0);
    }

    async _handleMessage(message) {
        const method = message.method || '';
        const id = message.id;
        const params = message.params || {};

        this.log(`Received: ${method}`);

        switch (method) {
            case 'ping':
                this._handlePing(id, params);
                break;
            case 'initialize':
                this._handleInitialize(id, params);
                break;
            case 'execute':
                await this._handleExecute(id, params);
                break;
            case 'input':
                await this._handleInput(id, params);
                break;
            case 'shutdown':
                this.running = false;
                break;
        }
    }

    _handlePing(id, params) {
        this.protocol.writeMessage({
            jsonrpc: '2.0',
            id: id,
            result: { timestamp: params.timestamp }
        });
    }

    _handleInitialize(id, params) {
        this.log('Initializing...');

        const commands = [];
        for (const [name, handler] of this.commands) {
            commands.push({ name, description: '' });
        }

        this.protocol.writeMessage({
            jsonrpc: '2.0',
            id: id,
            result: {
                name: this.name,
                version: this.version,
                description: this.description,
                protocol_version: '2.0',
                commands: commands
            }
        });

        this.log('Initialization complete');
    }

    async _handleExecute(id, params) {
        const functionName = params.function || '';
        const args = params.arguments || {};

        this.log(`Executing: ${functionName}`);

        this.currentRequestId = id;
        this.keepSession = false;

        const handler = this.commands.get(functionName);
        if (!handler) {
            this._sendError(id, -32601, `Unknown command: ${functionName}`);
            this.currentRequestId = null;
            return;
        }

        try {
            const result = await handler(args);
            this._sendComplete(id, true, result);
        } catch (err) {
            this._sendError(id, -1, err.message);
        }

        this.currentRequestId = null;
    }

    async _handleInput(id, params) {
        const content = params.content || '';

        this.log(`Input: ${content.substring(0, 50)}`);

        // Send acknowledgment
        this.protocol.writeMessage({
            jsonrpc: '2.0',
            id: id,
            result: { acknowledged: true }
        });

        this.currentRequestId = id;
        this.keepSession = false;

        const handler = this.commands.get('on_input');
        if (handler) {
            try {
                const result = await handler({ content });
                this._sendComplete(id, true, result);
            } catch (err) {
                this._sendError(id, -1, err.message);
            }
        } else {
            this._sendComplete(id, true, `Received: ${content}`);
        }

        this.currentRequestId = null;
    }

    _sendComplete(requestId, success, data) {
        this.protocol.writeMessage({
            jsonrpc: '2.0',
            method: 'complete',
            params: {
                request_id: requestId,
                success: success,
                data: data,
                keep_session: this.keepSession
            }
        });
    }

    _sendError(requestId, code, message) {
        this.protocol.writeMessage({
            jsonrpc: '2.0',
            method: 'error',
            params: {
                request_id: requestId,
                code: code,
                message: message
            }
        });
    }
}

module.exports = { Plugin, Protocol };

